def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    trains = image_patch.find("train")
    poles = image_patch.find("green poles")

    if not trains or not poles:
        return image_patch

    behind_poles = [t for t in trains if is_behind(t, poles[0])]

    if not behind_poles:
        return image_patch

    return depth_order(behind_poles)[-1]

